import {buildCouponCardsPdfAsync,loadCouponTemplate,downloadCouponPdf} from './coupon-card-pdf.js?v=1.6.66';
export function randomCardCode(){const digits=[];while(digits.length<10){for(const n of crypto.getRandomValues(new Uint8Array(16))){if(n>=250||(!digits.length&&n%10===0))continue;digits.push(String(n%10));if(digits.length===10)break;}}return digits.join('');}
export function createCouponCardPrinter({document,rpc,canEdit,run,notify,dates,template=loadCouponTemplate,build=buildCouponCardsPdfAsync,download=downloadCouponPdf}) {
 const $=id=>document.getElementById(id);let pending=null,lastBatch=null,lastPdf=null,epoch=0,loading=false,activeMode=false;
 const node=(tag,value)=>{const el=document.createElement(tag);el.textContent=value;return el;};
 const filename=batch=>'Taktooka-Free-Rides-'+batch.codes.length+'-'+batch.id.slice(0,8)+'.pdf';
 const number=n=>new Intl.NumberFormat('en-US').format(n);
 const progress=(label,done,total)=>{$('cardGenerated').textContent=label+': '+number(done)+' / '+number(total);};
 function sync(){$('downloadCards').disabled=!lastPdf;$('cardCount').disabled=!activeMode||!canEdit()||loading;}
 function mode({free,editing}){activeMode=free&&!editing;$('cardOptions').hidden=!free||editing;$('rewardCode').readOnly=free||editing;$('rewardUses').parentElement.hidden=free&&!editing;if(free&&!editing){if(!/^\d{10}$/.test($('rewardCode').value))$('rewardCode').value=randomCardCode();$('rewardUses').value=1;}$('rewardSave').textContent=free&&!editing?'توليد الكارتات':'حفظ الكود';$('cardPreviewCode').textContent=free&&!editing?$('rewardCode').value:'1234567890';sync();}
 async function complete(batch){let current=batch;while(current.generated_count<current.card_count){if(!canEdit())throw new Error('الدفعة تحتاج إكمال التوليد من حساب لديه صلاحية التعديل');progress('جاري توليد الكارتات',current.generated_count,current.card_count);const next=await rpc('fill',{id:current.id,after:current.generated_count});if(next.generated_count<=current.generated_count)throw new Error('توقف التوليد؛ أعد المحاولة لإكمال نفس الدفعة');current=next;}return current;}
 async function readCodes(batch){const codes=[];while(codes.length<batch.card_count){progress('جاري تجهيز الكارتات',codes.length,batch.card_count);const page=await rpc('get_page',{id:batch.id,offset:codes.length,limit:2000});if(!page.codes.length)throw new Error('الدفعة لم تكتمل؛ أعد المحاولة');codes.push(...page.codes);}if(codes.length!==batch.card_count)throw new Error('عدد الكارتات غير مطابق');return {...batch,codes};}
 async function makePdf(batch,image){return await build({...image,codes:batch.codes,onProgress:({page,total})=>progress('جاري تجهيز PDF',page,total)});}
 async function generate(){if(!canEdit()||loading)return;const count=Number($('cardCount').value.replace(/[,٬\s]/g,'')),expiry=new Date($('rewardExpiry').value).toISOString();if(!Number.isInteger(count)||count<1||count>100000)throw new Error('حدد من 1 إلى 100,000 كارت');loading=true;sync();try{const image=await template(),data={count,expires_at:expiry,active:$('rewardActive').checked,first_code:$('rewardCode').value},signature=JSON.stringify(data);if(pending?.signature!==signature)pending={signature,id:crypto.randomUUID(),...data};let batch=await rpc('start',pending);batch=await complete(batch);batch=await readCodes(batch);const pdf=await makePdf(batch,image);lastBatch=batch;lastPdf=pdf;pending=null;$('rewardCode').value=batch.codes[0];$('cardPreviewCode').textContent=batch.codes[0];$('cardGenerated').textContent='تم توليد '+number(batch.codes.length)+' كارت؛ كل كارت بكود مختلف واستخدام واحد.';notify('الكارتات جاهزة؛ اضغط تنزيل PDF');await load();}finally{loading=false;sync();}}
 async function load(){const current=++epoch,batches=await rpc('list');if(current!==epoch)return;const list=$('cardBatches');list.replaceChildren();for(const batch of batches){const row=node('article','');row.className='record';row.append(node('strong',number(batch.card_count)+' كارت'),node('p','تاريخ التوليد: '+dates(batch.created_at)+' · استُخدم '+batch.used_cards+' كارت'));const button=node('button','تنزيل PDF / إكمال التوليد');button.type='button';button.className='secondary';button.onclick=()=>run(async()=>{button.disabled=true;try{const image=await template();let result=await rpc('get_page',{id:batch.id,offset:0,limit:1});result=await complete(result);result=await readCodes(result);download(await makePdf(result,image),filename(result),document);}finally{button.disabled=false;}});row.append(button);list.append(row);}if(!batches.length)list.append(node('p','لا توجد دفعات طباعة بعد'));}
 $('downloadCards').onclick=()=>{if(lastPdf&&lastBatch)download(lastPdf,filename(lastBatch),document);};sync();return {mode,generate,load,sync};
}
